# Generated by build.py from recipe.yml for recipe ftp-give-a-group-write-access. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'team' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'team/plan.txt'), "plan v1`n")
[IO.File]::WriteAllText((Join-Path $PWD 'draft.txt'), "draft from ed`n")
[IO.File]::WriteAllText((Join-Path $PWD 'notes.txt'), "notes from erin`n")
[IO.File]::WriteAllText((Join-Path $PWD 'late.txt'), "a reader's edit`n")
$server0 = Start-Process surl -ArgumentList '--user', 'ed:edpass', '--user', 'erin:erinpass', '--user', 'rita:ritapass', '--user', 'gus:guspass', '--group', 'editors=ed,erin', '--group', 'readers=rita', '--share', 'team=team', '--share-access', '"team=@editors:rw,@readers:r"', '--allow-uploads', '--allow-plaintext-auth', '--list-directories', 'ftp://127.0.0.1:8080/', 'http://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -u ed:edpass -T draft.txt ftp://127.0.0.1:8080/team/draft.txt } finally { Stop-Process $server0 }
